WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity DESC NULLS LAST, id) AS row_num FROM order_items) x WHERE row_num = 1), metrics AS (SELECT *, MIN(unit_price) OVER w_ordered product_id_min_unit_price, SUM(quantity) OVER w_grp cumulative_quantity, CORR(quantity, unit_price) OVER (PARTITION BY product_id) corr_quantity_unit_price, FIRST_VALUE(quantity) IGNORE NULLS OVER w_grp first_known_quantity FROM deduped WINDOW w_ordered AS (PARTITION BY product_id, order_id), w_grp AS (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), base AS (SELECT *, FLOOR(product_id_min_unit_price) product_id_min_unit_price_whole FROM metrics WHERE product_id IS NOT NULL), with_windows AS (SELECT *, FIRST_VALUE(corr_quantity_unit_price) IGNORE NULLS OVER (PARTITION BY order_id ORDER BY product_id_min_unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_corr_quantity_unit_price, PERCENT_RANK() OVER (PARTITION BY product_id, order_id ORDER BY product_id_min_unit_price DESC NULLS LAST) product_id_min_unit_price_percent_rank FROM base), enriched AS (SELECT id, order_id, product_id, quantity, unit_price, row_num, product_id_min_unit_price, cumulative_quantity, corr_quantity_unit_price, first_known_quantity, product_id_min_unit_price_whole, first_known_corr_quantity_unit_price, product_id_min_unit_price_percent_rank, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY product_id_min_unit_price_whole DESC NULLS FIRST) product_id_min_unit_price_whole_percent_rank, NTILE(3) OVER (PARTITION BY order_id ORDER BY quantity DESC, id) quantity_bucket, SUM(product_id_min_unit_price_percent_rank) OVER (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_product_id_min_unit_price_percent_rank, AVG(quantity) OVER (PARTITION BY product_id ORDER BY first_known_quantity, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) quantity_avg_5 FROM with_windows) SELECT CASE WHEN unit_price >= 340 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, CASE WHEN product_id_min_unit_price >= 383 THEN 'HIGH' ELSE 'LOW' END AS product_id_min_unit_price_tier, SUM(product_id_min_unit_price_percent_rank) AS total_product_id_min_unit_price_percent_rank, BIT_AND(quantity) AS quantity_bit_and, ROUND(AVG(unit_price), 2) AS avg_unit_price, STDDEV_SAMP(unit_price) AS unit_price_stddev FROM enriched GROUP BY CASE WHEN unit_price >= 340 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN product_id_min_unit_price >= 383 THEN 'HIGH' ELSE 'LOW' END
